import {ToolRegistry} from './registry.js';

describe('ToolRegistry input schema validation', () => {
  it('rejects missing and wrong-typed input before execution while preserving valid extra keys', async () => {
    let executorCalls = 0;
    let receivedInput: Record<string, unknown> | undefined;
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'gets weather',
        inputSchema: {
          type: 'object',
          required: ['location'],
          properties: {location: {type: 'string'}},
        },
      },
      async input => {
        executorCalls++;
        receivedInput = input;
        return 'sunny';
      }
    );

    const missing = await registry.execute('weather', {});
    const wrongType = await registry.execute('weather', {location: 42});
    const valid = await registry.execute('weather', {location: 'Berlin', requestId: 'req-1'});

    expect(missing.result).toMatch(/location.*required/i);
    expect(wrongType.result).toMatch(/location/i);
    expect(wrongType.result).toMatch(/string/i);
    expect(wrongType.result).not.toContain('42');
    expect({valid, receivedInput, executorCalls}).toEqual({
      valid: {result: 'sunny'},
      receivedInput: {location: 'Berlin', requestId: 'req-1'},
      executorCalls: 1,
    });
  });

  it('validates a function-valued definition against the schema returned for each call', async () => {
    let schemaVersion: 'alpha' | 'beta' = 'alpha';
    let executorCalls = 0;
    const registry = new ToolRegistry();
    registry.register(
      () => ({
        name: 'versioned',
        description: 'uses a changing schema',
        inputSchema:
          schemaVersion === 'alpha'
            ? {type: 'object', required: ['alpha'], properties: {alpha: {type: 'string'}}}
            : {type: 'object', required: ['beta'], properties: {beta: {type: 'string'}}},
      }),
      async () => {
        executorCalls++;
        return 'ok';
      }
    );

    const first = await registry.execute('versioned', {beta: 'value'});
    schemaVersion = 'beta';
    const second = await registry.execute('versioned', {alpha: 'value'});

    expect(first.result).toMatch(/alpha/);
    expect(second.result).toMatch(/beta/);
    expect(executorCalls).toBe(0);
  });

  it('rejects an uncompilable static schema during registration and names the tool', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {name: 'broken-weather', description: 'has an invalid schema', inputSchema: {type: 'not-a-json-schema-type'}},
        async () => 'unreachable'
      )
    ).toThrow(/broken-weather/);
  });
});

