  it('returns a ToolResponse naming the missing field when a required property is absent', async () => {
    let executorCalls = 0;
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'gets weather',
        inputSchema: {type: 'object', required: ['location'], properties: {location: {type: 'string'}}},
      },
      async () => {
        executorCalls++;
        return 'sunny';
      }
    );

    const result = await registry.execute('weather', {});

    expect(result.result).toMatch(/location.*required/i);
    expect(executorCalls).toBe(0);
  });
});
